"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[6632],{73948:e=>{e.exports=JSON.parse('{"tag":{"label":"teachers","permalink":"/docs/next/tags/teachers","allTagsPath":"/docs/next/tags","count":17,"items":[{"id":"teachers/accounts-and-roles","title":"Accounts and roles","description":"Anyone can register. What you can do afterwards depends on your role, so read the roles table before planning a class.","permalink":"/docs/next/teachers/accounts-and-roles"},{"id":"teachers/designer/activities","title":"Activities","description":"The advanced and admin roles. The Activities entry of the sidebar is hidden for instructors.","permalink":"/docs/next/teachers/designer/activities"},{"id":"teachers/api-keys","title":"API keys and models","description":"Every role can add and manage its own keys. Only administrators can create system keys that are shared with other users.","permalink":"/docs/next/teachers/api-keys"},{"id":"teachers/designer/widgets","title":"Code editor widget","description":"Every role that can edit a problem can add widgets. Widgets only run on OpenAI models, because LEIA uses tool calls to read, edit and test the code.","permalink":"/docs/next/teachers/designer/widgets"},{"id":"teachers/designer/create-leia","title":"Create a LEIA with the AI assistant","description":"The advanced and admin roles. An instructor can follow every step but Finish LEIA will be refused, because the assistant creates a new behaviour and instructors cannot create behaviours. Instructors should use the quick start instead.","permalink":"/docs/next/teachers/designer/create-leia"},{"id":"teachers/index","title":"LEIA for teachers","description":"This guide explains every screen, button and field that a teacher meets while designing a LEIA, running it with students and reviewing the results. Read this page first. It introduces the vocabulary and the two applications, and it tells you which page of the guide answers each task.","permalink":"/docs/next/teachers/"},{"id":"teachers/workbench/leia-settings","title":"LEIA settings in a replication","description":"The owner of the replication, administrators and anyone with its share link.","permalink":"/docs/next/teachers/workbench/leia-settings"},{"id":"teachers/faq","title":"Limitations and FAQ","description":"Honest answers to the questions teachers ask most, plus the limits of the current version that are worth knowing before you plan a class.","permalink":"/docs/next/teachers/faq"},{"id":"teachers/workbench/live-and-spectate","title":"Live dashboard and spectating","description":"The owner of the replication and administrators. The spectate links themselves work for anyone who has them, without an account, for one hour.","permalink":"/docs/next/teachers/workbench/live-and-spectate"},{"id":"teachers/designer/components-reference","title":"Persona, Problem and Behaviour fields","description":"Every role can edit personas and problems. Editing a behaviour is reserved to the advanced and admin roles.","permalink":"/docs/next/teachers/designer/components-reference"},{"id":"teachers/workbench/replication-settings","title":"Replication settings","description":"The owner of the replication and administrators. People who received a share link can change the switches and regenerate the code but not rename the replication, change its language or manage sharing.","permalink":"/docs/next/teachers/workbench/replication-settings"},{"id":"teachers/workbench/results-and-export","title":"Results, grading and export","description":"The owner of the replication, administrators and anyone with its share link. Editing a score is reserved to administrators in the current interface.","permalink":"/docs/next/teachers/workbench/results-and-export"},{"id":"teachers/designer/test-leia","title":"Test a LEIA","description":"Every role can test any LEIA it can see, with its own keys or with the system keys.","permalink":"/docs/next/teachers/designer/test-leia"},{"id":"teachers/designer/index","title":"The LEIA library","description":"Every role can browse, test and design from the library. Add to activity and Quick replication appear only for the advanced and admin roles. Deleting is reserved to the owner of the LEIA and to administrators.","permalink":"/docs/next/teachers/designer/"},{"id":"teachers/designer/supervisor","title":"The supervisor","description":"Every role that can finish a LEIA can enable its supervisor. It needs an OpenAI key.","permalink":"/docs/next/teachers/designer/supervisor"},{"id":"teachers/workbench/students","title":"What students see","description":"Students need no account. Teachers can walk the same path with the Demo / test link of a replication, which creates a throwaway identity that is excluded from the results.","permalink":"/docs/next/teachers/workbench/students"},{"id":"teachers/workbench/index","title":"Workbench overview and your first replication","description":"The advanced and admin roles. Instructors are refused at the Workbench sign-in with \\"Instructors cannot access workbench administration.\\"","permalink":"/docs/next/teachers/workbench/"}],"unlisted":false}}')}}]);